package com.arcus.alert;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public class PriceMonitorService extends Service{
static final String CHANNEL="arcus_price_alerts",PREF="arcus_native";ScheduledExecutorService executor;final Set<String> fired=new HashSet<>();ToneGenerator tone;
public void onCreate(){super.onCreate();createChannel();tone=new ToneGenerator(AudioManager.STREAM_NOTIFICATION,100);startForeground(41,build("Watching Arcus prices · 1-second refresh"));executor=Executors.newSingleThreadScheduledExecutor();executor.scheduleAtFixedRate(this::checkPrices,0,1,TimeUnit.SECONDS);}
public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public IBinder onBind(Intent i){return null;}
void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Arcus price alerts",NotificationManager.IMPORTANCE_HIGH);c.setDescription("Price alerts and sound");c.enableVibration(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
Notification build(String s){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setContentTitle("Arcus Alert").setContentText(s).setOngoing(true).setSmallIcon(android.R.drawable.ic_dialog_info).build();}
JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}
void checkPrices(){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.arcus.xyz/v1/prices").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setUseCaches(false);c.setRequestProperty("Accept","application/json");InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);JSONObject d=new JSONObject(out.toString("UTF-8"));getSharedPreferences(PREF,0).edit().putString("markets_json",d.toString()).putLong("markets_updated",System.currentTimeMillis()).apply();JSONArray a=levels();for(int i=0;i<a.length();i++){JSONObject l=a.getJSONObject(i);String sym=l.getString("symbol").toUpperCase();double target=l.getDouble("price");int mode=l.optInt("mode",0);JSONObject item=find(d,sym);if(item==null)continue;Object raw=item.has("markPrice")&&!item.isNull("markPrice")?item.opt("markPrice"):item.opt("oraclePrice");if(raw==null)continue;double price=Double.parseDouble(raw.toString());String key=sym+"|"+target+"|"+mode+"|"+l.optLong("created");boolean hit=false;if(mode==0){String pk="prev:"+sym;String old=getSharedPreferences(PREF,0).getString(pk,"");if(!old.isEmpty()){double prev=Double.parseDouble(old);hit=(prev<target&&price>=target)||(prev>target&&price<=target);}getSharedPreferences(PREF,0).edit().putString(pk,Double.toString(price)).apply();}else if(mode==1)hit=Math.abs(price-target)/target<=0.0005;else hit=Math.abs(price-target)/target*100<=0.1;if(hit&&fired.add(key))alert(sym,target,price);}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(41,build("Monitoring · "+a.length()+" alerts · refreshed every second"));}catch(Exception e){getSharedPreferences(PREF,0).edit().putString("monitor_error",e.toString()).apply();}finally{if(c!=null)c.disconnect();}}
JSONObject find(JSONObject d,String s){Iterator<String> it=d.keys();while(it.hasNext()){JSONObject o=d.optJSONObject(it.next());if(o!=null&&s.equalsIgnoreCase(o.optString("marketDisplayName")))return o;}return null;}
void alert(String sym,double target,double price){String body=sym+" reached "+target+". Current price: "+price;Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);b.setContentTitle("Arcus price alert").setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setSmallIcon(android.R.drawable.ic_dialog_alert).setAutoCancel(true).setDefaults(Notification.DEFAULT_ALL);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%Integer.MAX_VALUE),b.build());try{tone.startTone(ToneGenerator.TONE_PROP_BEEP,700);}catch(Exception ignored){}getSharedPreferences(PREF,0).edit().putString("last_alert",body+" @ "+new Date()).apply();}
public void onDestroy(){if(executor!=null)executor.shutdownNow();if(tone!=null)tone.release();super.onDestroy();}
}